  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.07+sy*0.05-t*0.6)+Math.sin(sx*0.11-sy*0.08+t*1.4))/4;
  const fineBg=Math.sin((sx+sy)*0.12+t*2.5)*0.3+Math.sin((sx-sy)*0.1-t*2)*0.3+Math.sin(sx*0.2-t*3)*0.2+Math.sin(sy*0.18+t*2.7)*0.2;
